		Dimension removeSize = new Dimension(14, 20);
		removeBtn.setPreferredSize(removeSize);
		removeBtn.setMinimumSize(removeSize);
		removeBtn.setMaximumSize(removeSize);
		removeBtn.addActionListener(e ->
