package com.nyloer.roleswapper;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

enum MatchType
{
	EQUALS,
	STARTS_WITH,
	ENDS_WITH,
	CONTAINS,
	WILDCARD,
	IGNORE,
	;

	public boolean matches(String menuText, String swapText)
	{
		switch (this)
		{
			case IGNORE:
				return true;
			case EQUALS:
				return menuText.equals(swapText);
			case STARTS_WITH:
				return menuText.startsWith(swapText);
			case ENDS_WITH:
				return menuText.endsWith(swapText);
			case CONTAINS:
				return menuText.contains(swapText);
			case WILDCARD:
				return menuText.matches(swapText);
			default:
				// shouldn't happen.
				throw new IllegalStateException();
		}
	}

	public static MatchType getType(String s)
	{
		if (s == null)
		{
			return MatchType.IGNORE;
		}

		int star = s.indexOf('*');
		if (star == -1)
		{
			return MatchType.EQUALS;
		}
		if (star == 0)
		{
			if (s.length() == 1)
			{
				return MatchType.IGNORE;
			}
			star = s.indexOf('*', star + 1);
			if (star == -1)
			{
				return MatchType.ENDS_WITH;
			}
			if (star == s.length() - 1)
			{
				return MatchType.CONTAINS;
			}
		}
		else if (star == s.length() - 1)
		{
			return MatchType.STARTS_WITH;
		}

		return MatchType.WILDCARD;
	}

	public static String prepareMatch(String option, MatchType optionType)
	{
		return optionType == MatchType.WILDCARD ? generateWildcardMatcher(option) : removeStars(option);
	}

	private static String removeStars(String s)
	{
		return s == null ? s : s.replaceAll("\\*", "");
	}

	// copied from runelite.
	private static final Pattern WILDCARD_PATTERN = Pattern.compile("(?i)[^*]+|(\\*)");

	private static String generateWildcardMatcher(String pattern)
	{
		final Matcher matcher = WILDCARD_PATTERN.matcher(pattern);
		final StringBuffer buffer = new StringBuffer();

		buffer.append("(?i)");
		while (matcher.find())
		{
			if (matcher.group(1) != null)
			{
				matcher.appendReplacement(buffer, ".*");
			}
			else
			{
				matcher.appendReplacement(buffer, Matcher.quoteReplacement(Pattern.quote(matcher.group(0))));
			}
		}

		matcher.appendTail(buffer);
		return buffer.toString();
	}
}

package com.nyloer.npc;

public enum NyloType
{
	MELEE(new int[]{8342, 8345, 8348, 8351, 10774, 10777, 10780, 10783, 10791, 10794, 10797, 10800}),
	RANGE(new int[]{8343, 8346, 8349, 8352, 10775, 10778, 10781, 10784, 10792, 10795, 10798, 10801}),
	MAGE(new int[]{8344, 8347, 8350, 8353, 10776, 10779, 10782, 10785, 10793, 10796, 10799, 10802});

	private final int[] ids;

	NyloType(int[] ids)
	{
		this.ids = ids;
	}

	/** Returns the matching type for the given NPC ID, or null if not a nylocas. */
	public static NyloType fromId(int id)
	{
		for (NyloType type : values())
		{
			for (int npcId : type.ids)
			{
				if (npcId == id)
				{
					return type;
				}
			}
		}
		return null;
	}

	/** Lower-case name used as part of font config keys (e.g. "melee", "range", "mage"). */
	public String configKey()
	{
		return name().toLowerCase();
	}
}

package com.nyloer.npc;

import com.nyloer.NyloerConfig;
import com.nyloer.fonts.CustomFontConfig;
import java.awt.Color;
import java.awt.Font;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;

public class NyloerNpc
{
	@Getter private NPC npc;
	@Getter private int id;
	@Getter private int lastId;
	@Getter private NyloType type;
	@Getter private int index;
	@Getter private NyloSize size;
	@Getter @Setter private boolean isAlive;
	@Getter private boolean isSplit;
	@Getter private String spawn;
	@Getter private int waveSpawned;
	@Getter public int tickSpawned;
	@Getter private int ticksAlive;
	@Getter private String nyloerSymbol;
	@Getter private Color color;
	@Getter private Color outlineColor;
	@Getter private boolean colorDarker;
	@Getter private Font font;
	@Getter private String fontConfigKey;

	private final NyloerConfig config;
	private final CustomFontConfig customFontConfig;

	public NyloerNpc(NPC npc, Client client, NyloerConfig config, CustomFontConfig customFontConfig, int waveNumber, int lastWaveTickSpawned)
	{
		this.config = config;
		this.customFontConfig = customFontConfig;
		this.npc = npc;
		this.id = npc.getId();
		this.lastId = npc.getId();
		this.index = npc.getIndex();
		this.isAlive = true;
		this.spawn = findSpawn(npc, client);
		this.isSplit = spawn.equals("SPLIT");
		this.tickSpawned = client.getTickCount();
		this.colorDarker = false;
		this.waveSpawned = (isSplit && tickSpawned > lastWaveTickSpawned) ? waveNumber + 1 : waveNumber;
		this.ticksAlive = 0;
		updateStyle(id);
		configureFonts();
		this.size = NyloSize.fromNpcSize(npc.getComposition().getSize());
	}

	public void incrementTicks()
	{
		++ticksAlive;
		if (ticksAlive == 52)
		{
			isAlive = false;
		}
		if (lastId != npc.getId())
		{
			lastId = npc.getId();
			updateStyle(npc.getId());
		}
	}

	/** Called when this NPC is the first of a new wave; bumps waveSpawned and refreshes style. */
	public void bumpWave()
	{
		++waveSpawned;
		updateStyle(id);
	}

	private void updateStyle(int npcId)
	{
		type = NyloType.fromId(npcId);
		if (type == null)
		{
			fontConfigKey = null;
			color = Color.WHITE;
			outlineColor = Color.BLACK;
			isAlive = false;
			return;
		}

		fontConfigKey = waveSpawned + "-" + type.configKey();
		switch (type)
		{
			case MELEE:
				color = config.meleeNylocasColor();
				outlineColor = config.meleeNylocasOutlineColor();
				nyloerSymbol = config.meleeNylocasSymbol();
				break;
			case RANGE:
				color = config.rangeNylocasColor();
				outlineColor = config.rangeNylocasOutlineColor();
				nyloerSymbol = config.rangeNylocasSymbol();
				break;
			case MAGE:
				color = config.mageNylocasColor();
				outlineColor = config.mageNylocasOutlineColor();
				nyloerSymbol = config.mageNylocasSymbol();
				break;
		}

		Color customColor = customFontConfig.getColor(fontConfigKey);
		if (customColor != null)
		{
			color = customColor;
		}
	}

	private void configureFonts()
	{
		int fontStyle;
		if (isSplit)
		{
			fontStyle = config.splitFontsBold() ? Font.BOLD : Font.PLAIN;
			this.font = new Font(config.splitFontsType().toString(), fontStyle, config.splitFontsSize());
		}
		else
		{
			fontStyle = config.fontsBold() ? Font.BOLD : Font.PLAIN;
			this.font = new Font(config.fontsType().toString(), fontStyle, config.fontsSize());
		}
	}

	private static String findSpawn(NPC npc, Client client)
	{
		WorldPoint wp = WorldPoint.fromLocalInstance(client, npc.getLocalLocation());
		int x = wp.getRegionX();
		int y = wp.getRegionY();
		if (x == 17 && y == 25) return "WEST NORTH";
		if (x == 17 && y == 24) return "WEST SOUTH";
		if (x == 31 && y == 9)  return "SOUTH WEST";
		if (x == 32 && y == 9)  return "SOUTH EAST";
		if (x == 46 && y == 24) return "EAST SOUTH";
		if (x == 46 && y == 25) return npc.getComposition().getSize() == 1 ? "EAST NORTH" : "EAST BIG";
		if (x == 18 && y == 25) return "WEST BIG";
		if (x == 32 && y == 10) return "SOUTH BIG";
		if (x == 47 && y == 25) return "EAST BIG 30";
		return "SPLIT";
	}
}

package com.nyloer.npc;

public enum NyloSize
{
	SMALL,
	BIG;

	public static NyloSize fromNpcSize(int npcSize)
	{
		return npcSize == 1 ? SMALL : BIG;
	}
}

package com.nyloer.overlays;

import com.google.common.collect.ArrayListMultimap;
import com.nyloer.NyloerConfig;
import com.nyloer.NyloerPlugin;
import com.nyloer.npc.NyloSize;
import com.nyloer.npc.NyloerNpc;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.stream.IntStream;
import javax.inject.Inject;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.game.NpcUtil;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

public class NyloerOverlay extends Overlay
{
	public ArrayListMultimap<WorldPoint, NyloerNpc> nyloers;
	private final NyloerConfig config;
	private final NyloerPlugin plugin;
	private final NpcUtil npcUtil;

	@Inject
	private NyloerOverlay(NyloerPlugin plugin, NyloerConfig config, NpcUtil npcUtil)
	{
		this.setPosition(OverlayPosition.DYNAMIC);
		this.setPriority(OverlayPriority.HIGH);
		this.setLayer(OverlayLayer.UNDER_WIDGETS);
		this.npcUtil = npcUtil;
		this.plugin = plugin;
		this.config = config;
		this.nyloers = ArrayListMultimap.create();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		this.nyloers.clear();
		if (this.plugin.getNylocasAliveCount() == 0)
		{
			return null;
		}
		nyloers = ArrayListMultimap.create();
		int length = this.plugin.getNyloers().size();
		for (int i = length - 1; i >= 0; i--)
		{
			NyloerNpc nyloer = this.plugin.getNyloers().get(i);
			if (nyloer.isAlive() && !npcUtil.isDying(nyloer.getNpc()))
			{
				nyloers.put(nyloer.getNpc().getWorldLocation(), nyloer);
			}
		}
		if (!nyloers.isEmpty())
		{
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			nyloers.asMap().forEach(
				(worldPoint, npcs) -> {
					int offset = 0;
					for (NyloerNpc nyloer : npcs)
					{
						graphics.setFont(nyloer.getFont());
						this.draw(graphics, nyloer, offset);
						offset += graphics.getFontMetrics().getHeight();
					}
				});
		}
		return null;
	}

	private boolean shouldDim(NyloerNpc nyloer)
	{
		if (nyloer.isColorDarker())
		{
			return true;
		}
		for (int[] rule : plugin.getActiveDimRules())
		{
			boolean sizeMatch = (nyloer.getSize() == NyloSize.SMALL && rule[1] == 1)
				|| (nyloer.getSize() == NyloSize.BIG && rule[2] == 1);
			if (sizeMatch && nyloer.getTickSpawned() <= rule[0])
			{
				return true;
			}
		}
		return false;
	}

	private void draw(Graphics2D graphics, NyloerNpc nyloer, int offset)
	{
		String prefix;
		String text;
		if (nyloer.isSplit())
		{
			prefix = config.splitPrefix();
		}
		else
		{
			prefix = config.wavePrefix();
		}
		if (config.showNylocasWave())
		{
			text = prefix + nyloer.getWaveSpawned();
		}
		else if (config.showNylocasSymbol())
		{
			text = prefix + nyloer.getNyloerSymbol();
		}
		else
		{
			text = prefix;
		}
		Point canvasTextLocation = nyloer.getNpc().getCanvasTextLocation(graphics, text, 0);
		if (canvasTextLocation == null)
		{
			return;
		}
		int x = canvasTextLocation.getX();
		int y = canvasTextLocation.getY() + offset;
		graphics.setColor(nyloer.getOutlineColor());
		IntStream.range(-1, 2).forEachOrdered(ex -> {
			IntStream.range(-1, 2).forEachOrdered(ey -> {
				if (ex != 0 && ey != 0)
				{
					graphics.drawString(text, x + ex, y + ey);
				}
			});
		});
		Color color = nyloer.getColor();
		if (shouldDim(nyloer))
		{
			color = color.darker().darker();
		}
		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}
}

package com.nyloer.overlays;

import com.nyloer.NyloerConfig;
import com.nyloer.NyloerPlugin;
import com.nyloer.npc.NyloType;
import com.nyloer.npc.NyloerNpc;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.awt.Stroke;
import javax.inject.Inject;
import lombok.Setter;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.NpcUtil;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;


public class NyloerTileOverlay extends Overlay
{
	private final NyloerConfig config;
	private final NyloerPlugin plugin;
	private final NpcUtil npcUtil;

	Stroke highlightWidth;

	@Setter
	private boolean renderMage;
	@Setter
	private boolean renderRange;
	@Setter
	private boolean renderMelee;

	@Inject
	private NyloerTileOverlay(NyloerPlugin plugin, NyloerConfig config, NpcUtil npcUtil)
	{
		this.setPosition(OverlayPosition.DYNAMIC);
		this.setPriority(OverlayPriority.HIGH);
		this.setLayer(OverlayLayer.ABOVE_SCENE);
		this.npcUtil = npcUtil;
		this.plugin = plugin;
		this.config = config;

		this.renderMage = false;
		this.renderRange = false;
		this.renderMelee = false;

		this.highlightWidth = new BasicStroke((float) config.tileHighlightWidth());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged configChanged)
	{
		if (!configChanged.getGroup().equals(NyloerConfig.GROUP))
		{
			this.highlightWidth = new BasicStroke((float) config.tileHighlightWidth());
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (this.plugin.getNylocasAliveCount() == 0)
		{
			return null;
		}
		for (NyloerNpc nyloer : this.plugin.getNyloersIndexMap().values())
		{
			if ((nyloer.isAlive()) && (!npcUtil.isDying(nyloer.getNpc())))
			{
				switch (nyloer.getType())
				{
					case MAGE:
						if (renderMage)
						{
							drawTile(graphics, nyloer, config.displayMageTilesAsTrueTiles());
						}
						break;
					case RANGE:
						if (renderRange)
						{
							drawTile(graphics, nyloer, config.displayRangeTilesAsTrueTiles());
						}
						break;
					case MELEE:
						if (renderMelee)
						{
							drawTile(graphics, nyloer, config.displayMeleeTilesAsTrueTiles());
						}
						break;
				}
			}
		}
		return null;
	}

	private void drawTile(Graphics2D graphics, NyloerNpc nyloer, boolean trueTile)
	{
		if (trueTile)
		{
			drawTrueTile(graphics, nyloer);
		}
		else
		{
			Polygon polygon = nyloer.getNpc().getCanvasTilePoly();
			if (polygon != null)
			{
				OverlayUtil.renderPolygon(graphics, polygon, nyloer.getColor(), highlightWidth);
			}
		}
	}

	private void drawTrueTile(Graphics2D graphics, NyloerNpc nyloer)
	{
		NPC npc = nyloer.getNpc();
		NPCComposition npcComposition = npc.getTransformedComposition();
		LocalPoint lp = LocalPoint.fromWorld(plugin.client, npc.getWorldLocation());
		if (lp == null || npcComposition == null)
		{
			return;
		}
		final int size = npcComposition.getSize();
		final LocalPoint centerLp = lp.plus(
			Perspective.LOCAL_TILE_SIZE * (size - 1) / 2,
			Perspective.LOCAL_TILE_SIZE * (size - 1) / 2);
		Polygon tilePoly = Perspective.getCanvasTileAreaPoly(plugin.client, centerLp, size);
		renderPoly(graphics, nyloer.getColor(), highlightWidth, tilePoly);
	}

	private void renderPoly(Graphics2D graphics, Color borderColor, Stroke borderStroke, Shape polygon)
	{
		if (polygon != null)
		{
			graphics.setColor(borderColor);
			graphics.setStroke(borderStroke);
			graphics.draw(polygon);
		}
	}
}

